function routeText(p){return '沪上集章计划 '+p.d+'\n预计新增 '+p.best.count+' 枚（交通时间仅供参考，请核对预约）\n'+p.best.steps.map((s,i)=>(i+1)+'. '+clock(s.arrival)+'–'+clock(s.end)+' '+s.v.name+'（'+s.v.address+'） +'+s.gain+'枚').join('\n')}
